"""Inheritance flags for the objects the host hands to its helpers.

On Windows, "can a child get this object" is the ``HANDLE_FLAG_INHERIT`` bit of
the *object handle*, which is what :func:`set_inheritable` and
:func:`is_inheritable` read and write here.  The flag lives in the kernel
handle table, so a change made through this module is immediately visible to
any other reader of the same handle (``GetHandleInformation``,
``os.get_inheritable`` on a descriptor wrapping it, an external debugger).
"""

from . import _winapi
from .errors import WSpawnError, from_oserror, require_windows


def _as_handle(handle):
    """Return ``handle`` as a plain integer object handle.

    Accepts a raw handle value or any object exposing ``fileno()`` (an open
    file, a socket, a pipe wrapper); descriptors are translated to the
    underlying Win32 handle so that the flag is set on the object itself.
    """
    if isinstance(handle, bool):
        raise WSpawnError("handle must be an object handle, got %r" % (handle,), kind="badarg")
    if isinstance(handle, int):
        return int(handle)
    if isinstance(handle, (str, bytes, bytearray)):
        raise WSpawnError("handle must be an integer, got %r" % (handle,), kind="badarg")

    fileno = getattr(handle, "fileno", None)
    if fileno is not None:
        require_windows("translating a file descriptor to an object handle")
        import msvcrt

        try:
            descriptor = fileno()
        except Exception as exc:
            raise WSpawnError(
                "could not read a descriptor from %r: %s" % (handle, exc), kind="badarg"
            ) from exc
        try:
            return int(msvcrt.get_osfhandle(descriptor))
        except OSError as exc:
            raise from_oserror(exc, "resolving the object handle", handle=handle) from exc

    try:
        return int(handle)
    except (TypeError, ValueError):
        raise WSpawnError("handle must be an integer, got %r" % (handle,), kind="badarg") from None


def _flags(number, operation, handle):
    try:
        return _winapi.get_handle_information(number)
    except ValueError as exc:
        raise WSpawnError(str(exc), kind="badarg", handle=handle) from exc
    except OSError as exc:
        raise from_oserror(exc, operation, handle=handle) from exc


def set_inheritable(handle, enabled=True):
    """Mark ``handle`` as transferable to child processes, or stop it being so.

    The change is made on the Win32 object handle and can be read back from
    outside this module.  Objects that do not carry an inheritance flag raise
    ``WSpawnError(kind="unsupported")``.
    """
    number = _as_handle(handle)
    require_windows("setting the inheritance flag")
    flags = _winapi.HANDLE_FLAG_INHERIT if enabled else 0
    try:
        _winapi.set_handle_information(number, _winapi.HANDLE_FLAG_INHERIT, flags)
    except ValueError as exc:
        raise WSpawnError(str(exc), kind="badarg", handle=handle) from exc
    except OSError as exc:
        raise from_oserror(exc, "setting the inheritance flag", handle=handle) from exc


def is_inheritable(handle):
    """Return ``True`` when ``handle`` is currently transferable to children."""
    number = _as_handle(handle)
    require_windows("reading the inheritance flag")
    flags = _flags(number, "reading the inheritance flag", handle)
    return bool(flags & _winapi.HANDLE_FLAG_INHERIT)


def inheritable_handles():
    """Return every object in this process that is currently transferable.

    Windows has no call that enumerates a process's own handle table, so the
    table is probed for live handles carrying ``HANDLE_FLAG_INHERIT``.  The
    result is a snapshot: a handle closed or re-flagged afterwards is stale.
    """
    require_windows("enumerating inheritable handles")
    return _winapi.probe_inheritable_handles()

"""Classification of the objects the host may hand to its helpers."""

from . import _winapi
from .errors import WSpawnError, from_oserror, require_windows
from .inherit import _as_handle


def handle_kind(handle):
    """Return ``"file"``, ``"pipe"``, ``"console"`` or ``"unknown"``.

    ``"unknown"`` is for live objects that are not file-like -- events,
    mutexes, process and thread handles.  An invalid handle is an error, not an
    unknown kind.
    """
    number = _as_handle(handle)
    require_windows("classifying an object handle")

    # Separate a dead handle from a live one that simply is not file-like:
    # GetFileType reports FILE_TYPE_UNKNOWN for both.
    try:
        _winapi.get_handle_information(number)
    except ValueError as exc:
        raise WSpawnError(str(exc), kind="badarg", handle=handle) from exc
    except OSError as exc:
        raise from_oserror(exc, "classifying an object handle", handle=handle) from exc

    try:
        kind = _winapi.file_type(number)
    except OSError:
        # Live handle, but GetFileType will not speak about it.
        return "unknown"

    kind &= ~_winapi.FILE_TYPE_REMOTE
    if kind == _winapi.FILE_TYPE_DISK:
        return "file"
    if kind == _winapi.FILE_TYPE_PIPE:
        return "pipe"
    if kind == _winapi.FILE_TYPE_CHAR:
        return _char_device_kind(number)
    return "unknown"


def _char_device_kind(number):
    """Tell a console apart from the other character devices."""
    if _winapi.is_console_handle(number):
        return "console"
    name = _winapi.object_name(number)
    if name and "ConDrv" in name:
        return "console"
    if name is None:
        # No name to go on; character devices reaching a helper are consoles
        # far more often than not.
        return "console"
    return "unknown"

"""Starting helper processes with a handover of the caller's objects.

The handover is the point of this module: a helper must end up holding exactly
the objects named in ``inherit`` (plus whatever standard streams the caller
asked for) and nothing else, no matter what else the host happens to have open
and flagged inheritable at the time.

Windows gives one mechanism with that guarantee: create the process with
``bInheritHandles=TRUE`` and a ``PROC_THREAD_ATTRIBUTE_HANDLE_LIST`` process
attribute naming the handles allowed across.  The kernel then duplicates *only*
those handles into the child, and it duplicates them under the same numeric
value, which is what lets the caller tell the helper "read handle 0x1a4".
``close_fds``-style descriptor hygiene is a different mechanism with different
semantics and is not a substitute.
"""

import os
import subprocess

from . import _winapi
from .errors import WSpawnError, from_oserror, require_windows
from .inherit import _as_handle


class SpawnedProcess(object):
    """A helper process started by :func:`spawn`."""

    def __init__(self, popen, inherit):
        self._popen = popen
        self.inherit = tuple(inherit)
        self.pid = popen.pid
        self.returncode = None

    def wait(self, timeout=None):
        self.returncode = self._popen.wait(timeout=timeout)
        return self.returncode

    def poll(self):
        self.returncode = self._popen.poll()
        return self.returncode

    def terminate(self):
        self._popen.terminate()


def _normalise_argv(argv):
    if isinstance(argv, (str, bytes, bytearray)):
        raise WSpawnError("argv must be a sequence of arguments, not a single string", kind="badarg")
    try:
        items = [os.fspath(item) for item in argv]
    except TypeError as exc:
        raise WSpawnError("argv must be an iterable of paths: %s" % exc, kind="badarg") from exc
    if not items:
        raise WSpawnError("argv must not be empty", kind="badarg")
    return items


def _normalise_handles(inherit):
    """Return the requested handles as a de-duplicated tuple of integers."""
    if inherit is None:
        return ()
    if isinstance(inherit, int):
        raise WSpawnError("inherit must be a sequence of handles, not a single handle", kind="badarg")
    if isinstance(inherit, (str, bytes, bytearray)):
        raise WSpawnError("inherit must be a sequence of handles, not a string", kind="badarg")
    try:
        items = list(inherit)
    except TypeError as exc:
        raise WSpawnError("inherit must be an iterable of handles: %s" % exc, kind="badarg") from exc

    handles = []
    for item in items:
        number = _as_handle(item)
        if number not in handles:
            handles.append(number)
    return tuple(handles)


def _check_handles(handles):
    """Fail early, and with a classified error, on anything unusable."""
    for number in handles:
        try:
            _winapi.get_handle_information(number)
        except ValueError as exc:
            raise WSpawnError(str(exc), kind="badarg", handle=number) from exc
        except OSError as exc:
            raise from_oserror(exc, "handing over an object", handle=number) from exc


def _make_inheritable(handles):
    """Flag ``handles`` inheritable, returning what is needed to undo it.

    ``CreateProcess`` rejects a handle list containing a handle that is not
    flagged inheritable, so the flag is forced on for the duration of the call
    and put back afterwards: the child's copies are made during process
    creation and are unaffected by the restore.
    """
    restore = []
    try:
        for number in handles:
            flags = _winapi.get_handle_information(number)
            if not flags & _winapi.HANDLE_FLAG_INHERIT:
                _winapi.set_handle_information(
                    number, _winapi.HANDLE_FLAG_INHERIT, _winapi.HANDLE_FLAG_INHERIT)
                restore.append(number)
    except OSError as exc:
        _restore(restore)
        raise from_oserror(exc, "flagging an object inheritable", handle=number) from exc
    except BaseException:
        _restore(restore)
        raise
    return restore


def _restore(handles):
    for number in handles:
        try:
            _winapi.set_handle_information(number, _winapi.HANDLE_FLAG_INHERIT, 0)
        except OSError:
            # Nothing useful to do while unwinding; the handover already
            # happened or already failed.
            pass


def _startupinfo(handles):
    """Return a ``STARTUPINFO`` restricting inheritance to ``handles``."""
    info = subprocess.STARTUPINFO()
    try:
        info.lpAttributeList = {"handle_list": list(handles)}
    except (AttributeError, TypeError) as exc:
        raise WSpawnError(
            "this Python build cannot restrict handle inheritance to an explicit "
            "list: %s" % exc,
            kind="unsupported",
        ) from exc
    # subprocess filters the list it is given; if the handles the caller asked
    # for do not survive that, the handover cannot be made exact.
    survivors = info.lpAttributeList.get("handle_list")
    if sorted(set(survivors or ())) != sorted(set(handles)):
        raise WSpawnError(
            "these objects cannot be named in a process handle list: %r"
            % (sorted(set(handles) - set(survivors or ())),),
            kind="unsupported",
        )
    return info


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The helper can reach the objects in ``inherit`` -- under the same handle
    values the caller passed -- plus any of ``stdin``/``stdout``/``stderr``
    given here.  Nothing else of the caller's crosses over, including objects
    that are currently flagged inheritable.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    if handles:
        require_windows("handing over specific objects to a helper")

    kwargs = {
        # Inheritance is restricted by the handle list below, not by letting
        # everything through; close_fds keeps the descriptor layer from
        # widening that.
        "close_fds": True,
        "stdin": stdin,
        "stdout": stdout,
        "stderr": stderr,
    }

    restore = ()
    if handles:
        _check_handles(handles)
        kwargs["startupinfo"] = _startupinfo(handles)
        restore = _make_inheritable(handles)

    try:
        popen = subprocess.Popen(command, **kwargs)
    except OSError as exc:
        raise from_oserror(exc, "starting the helper") from exc
    finally:
        _restore(restore)
    return SpawnedProcess(popen, handles)

