        dropped = sorted(set(handles) - survivors)
        if dropped:
            raise WSpawnError(
                "these objects cannot be named in a process handle list: %r" % (dropped,),
                kind="unsupported",
            )

    try:
        info.lpAttributeList = {"handle_list": list(handles)}
    except (AttributeError, TypeError, ValueError) as exc:
        raise WSpawnError(
            "this Python build cannot restrict handle inheritance to an explicit "
            "list: %s" % exc,
            kind="unsupported",
        ) from exc
    return info


def spawn(argv, inherit=(), stdin=None, stdout=None, stderr=None):
    """Start a helper process, handing it the objects named in ``inherit``.

    The helper can reach the objects in ``inherit`` -- under the same handle
    values the caller passed in -- plus any of ``stdin``/``stdout``/``stderr``
    given here.  Nothing else belonging to the caller crosses over, including
    objects that happen to be flagged inheritable.

    Returns a :class:`SpawnedProcess`.
    """
    command = _normalise_argv(argv)
    handles = _normalise_handles(inherit)

    if handles:
        require_windows("handing over specific objects to a helper")

    kwargs = {
        # Inheritance is narrowed by the handle list below rather than by
        # letting everything through; close_fds keeps the descriptor layer
        # from widening it again.
        "close_fds": True,
        "stdin": stdin,
        "stdout": stdout,
        "stderr": stderr,
    }

    restore = ()
    if handles:
        _check_handles(handles)
        kwargs["startupinfo"] = _startupinfo(handles)
        restore = _make_inheritable(handles)

    try:
        popen = subprocess.Popen(command, **kwargs)
    except OSError as exc:
        raise from_oserror(exc, "starting the helper") from exc
    finally:
        _restore(restore)
    return SpawnedProcess(popen, handles)
